with filtered as (select id, customer_id, store_id, order_date, status, channel, amount, case when status in ('PENDING', 'RETURNED') then 'Tier 1' else 'Other' end as status_group, coalesce(channel, 'NONE') as channel_clean from orders where channel is not null) select src.id, src.customer_id, src.store_id, src.status, src.channel, src.status_group, src.channel_clean, p.sqft, p.region, p.opened_date from filtered src join stores p on src.store_id = p.id;
